// =====================================================================
// Varre as Ordens de Servico da Omie e extrai o vinculo RF -> OS.
// Mode: Run Once for All Items
//
// DESCOBERTA (sondagem de 10/08/2026): o RF NAO esta na NFS-e, esta na OS.
// O ObterNFSe nao traz o RF. O ListarOS traz -- e em 3 campos que concordam:
//   Observacoes.cObsOS                       -> o RF PURO ("6203092738")
//   InformacoesAdicionais.cDadosAdicNF       -> "No RF:6203092738 | No Contrato:..."
//   Cabecalho.cCodIntOS                      -> "OS-VALE-<CNPJ>-<RF>-<seq>"
//
// PEGADINHA CRITICA: sem apenas_importado_api = "S" vem so' 157 OSs (as
// criadas a mao). As da esteira sao criadas via API e ficam de fora do
// filtro padrao. Com "S" vem ~3.734.
//
// CUSTO: ~187 chamadas (20/pagina) para 3.734 OSs -- e nao 1 por nota.
// O ListarOS devolve o registro COMPLETO, entao nao precisa ConsultarOS.
// =====================================================================

const cfg       = $input.first().json;
const appKey    = cfg.OMIE_APP_KEY;
const appSecret = cfg.OMIE_APP_SECRET;
const DRY_RUN   = String(cfg.DRY_RUN) === 'true';

if (!appKey || !appSecret || String(appKey).indexOf('COLE_') === 0) {
  throw new Error('Preencha OMIE_APP_KEY e OMIE_APP_SECRET no no Config.');
}

const POR_PAGINA     = Number(cfg.POR_PAGINA || 50);
const PAGINA_INICIAL = Number(cfg.PAGINA_INICIAL || 1);

// MODO = INCREMENTAL (padrao, para o agendado) ou COMPLETO.
//
// O ListarOS devolve as OS em ordem CRESCENTE de numero, entao as NOVAS
// estao nas ULTIMAS paginas. O incremental le a primeira pagina (so' para
// descobrir total_de_paginas) + as N ultimas: ~4 chamadas por dia em vez
// das ~75 de uma varredura completa.
//
// PAGINAS_DO_FIM = 3 a 50/pagina = as 150 OS mais recentes. Isso e' de
// proposito uma JANELA MOVEL, nao "so' as de ontem": a OS pode ser criada
// antes da nota existir na NF, e o JOIN ignora OS sem nota. Reler os
// ultimos dias garante que o vinculo apareca quando a nota chegar.
//
// Rode COMPLETO uma vez por mes (ou se desconfiar de buraco): o
// INSERT IGNORE torna reprocessar inofensivo.
const MODO           = String(cfg.MODO || 'INCREMENTAL').toUpperCase();
const PAGINAS_DO_FIM = Math.max(1, Number(cfg.PAGINAS_DO_FIM || 3));
const PAUSA_MS       = 300;
const MAX_TENTATIVAS = 3;
const ESPERA_RETRY_MS = [5000, 15000, 30000];

// RF da Vale: EXATOS 10 digitos comecando em 62.
// Nao usar \b62\d{8,12}\b: isso casa CNPJ (ex. 62002498000189).
const RF_EXATO = /(?<!\d)62\d{8}(?!\d)/;
const RF_ROTULADO = /N.\s*RF\s*:\s*(\d{10})/i;

const chamar = (opcoes) => this.helpers.httpRequest(opcoes);

function motivoOmie(e) {
  const cands = [
    e && e.response && e.response.data,
    e && e.response && e.response.body,
    e && e.cause && e.cause.response && e.cause.response.data,
    e && e.error, e && e.description,
  ];
  for (const c of cands) {
    if (!c) continue;
    let o = c;
    if (typeof o === 'string') {
      try { o = JSON.parse(o); } catch (_) { return o.slice(0, 400); }
    }
    if (o && (o.faultstring || o.faultcode)) {
      return String(o.faultcode || '') + ' ' + String(o.faultstring || '');
    }
    try { return JSON.stringify(o).slice(0, 400); } catch (_) { /* segue */ }
  }
  return e && e.message ? String(e.message) : 'sem detalhe no corpo';
}

async function pedirPagina(p) {
  let ultimo = null;
  for (let t = 0; t < MAX_TENTATIVAS; t++) {
    try {
      return await chamar({
        method: 'POST',
        url: 'https://app.omie.com.br/api/v1/servicos/os/',
        headers: { 'Content-Type': 'application/json' },
        body: {
          call: 'ListarOS', app_key: appKey, app_secret: appSecret,
          param: [{
            pagina: p,
            registros_por_pagina: POR_PAGINA,
            apenas_importado_api: 'S',
          }],
        },
        json: true,
      });
    } catch (e) {
      ultimo = e;
      console.warn('pagina ' + p + ', tentativa ' + (t + 1) + '/' + MAX_TENTATIVAS
        + ' -> ' + motivoOmie(e));
      if (t < MAX_TENTATIVAS - 1) await new Promise((s) => setTimeout(s, ESPERA_RETRY_MS[t]));
    }
  }
  const err = new Error('A Omie recusou a pagina ' + p + ' em ' + MAX_TENTATIVAS
    + ' tentativas. MOTIVO: ' + motivoOmie(ultimo)
    + ' | Retome com PAGINA_INICIAL = ' + p + ' no no Config.');
  err.pagina = p;
  throw err;
}

function extrairRF(os) {
  const cab  = os.Cabecalho || {};
  const obs  = String((os.Observacoes || {}).cObsOS || '');
  const adic = String((os.InformacoesAdicionais || {}).cDadosAdicNF || '');
  const cint = String(cab.cCodIntOS || '');

  const mObs  = obs.match(RF_EXATO);
  const mRot  = adic.match(RF_ROTULADO);
  const mAdic = mRot ? mRot[1] : (adic.match(RF_EXATO) || [null])[0];
  const mInt  = cint.match(RF_EXATO);

  const fontes = {
    obs: mObs ? mObs[0] : null,
    adic: mAdic || null,
    codint: mInt ? mInt[0] : null,
  };
  const valores = [fontes.obs, fontes.adic, fontes.codint].filter(Boolean);
  const distintos = [...new Set(valores)];

  return {
    rf: distintos.length === 1 ? distintos[0] : (fontes.obs || fontes.adic || fontes.codint || null),
    fontes: fontes,
    qtd_fontes: valores.length,
    divergente: distintos.length > 1,
  };
}

const pares = [];      // {rf, cNumOs, status_nota, qtd_fontes}
const divergentes = []; // RF diferente entre os 3 campos
let osLidas = 0, osSemRF = 0, chamadas = 0;
let totalPaginas = 1, totalRegistros = null;
let parcial = false, proxima_pagina = null, motivo_parada = null;

function processar(r) {
  const lista = r.osCadastro || r.os_cadastro || [];
  for (const os of lista) {
    osLidas++;
    const cab  = os.Cabecalho || {};
    const info = os.InfoCadastro || {};
    const achado = extrairRF(os);

    if (!achado.rf) { osSemRF++; continue; }          // OS que nao e' da Vale
    if (achado.divergente) divergentes.push({ cNumOS: cab.cNumOS, fontes: achado.fontes });

    // A OS ja' diz se foi faturada/cancelada -- status de graca.
    const cancelada = String(info.cCancelada || '').toUpperCase() === 'S';
    const faturada  = String(info.cFaturada  || '').toUpperCase() === 'S';

    pares.push({
      rf: achado.rf,
      // NF.cNumOs guarda com 15 digitos e zeros a esquerda
      cNumOs: String(cab.cNumOS == null ? '' : cab.cNumOS).padStart(15, '0'),
      status_nota: cancelada ? 'CANCELADA' : (faturada ? 'FATURADA' : null),
      qtd_fontes: achado.qtd_fontes,
    });
  }
}

// ---- 1) primeira pagina: tambem serve para descobrir total_de_paginas ----
const primeira = await pedirPagina(PAGINA_INICIAL);
chamadas++;
totalPaginas   = Number(primeira.total_de_paginas || 1);
totalRegistros = primeira.total_de_registros == null ? null : Number(primeira.total_de_registros);
processar(primeira);
console.log('pagina ' + PAGINA_INICIAL + '/' + totalPaginas + ' (' + totalRegistros + ' OS na conta)');

// ---- 2) que paginas ainda ler ----
const fila = [];
if (MODO === 'COMPLETO') {
  for (let p = PAGINA_INICIAL + 1; p <= totalPaginas; p++) fila.push(p);
} else {
  const inicio = Math.max(PAGINA_INICIAL + 1, totalPaginas - PAGINAS_DO_FIM + 1);
  for (let p = inicio; p <= totalPaginas; p++) fila.push(p);
}
console.log('modo ' + MODO + ': ' + (fila.length + 1) + ' chamada(s) no total'
  + (MODO === 'COMPLETO' ? '' : ' (paginas do fim: ' + fila.join(',') + ')'));

// ---- 3) le a fila ----
for (const p of fila) {
  await new Promise((s) => setTimeout(s, PAUSA_MS));
  let r;
  try {
    r = await pedirPagina(p);
  } catch (e) {
    if (!pares.length) throw e;   // nada colhido: falha de verdade
    parcial = true;
    proxima_pagina = e.pagina || p;
    motivo_parada = e.message;
    console.warn('PARCIAL: parou na pagina ' + proxima_pagina + ' com ' + pares.length + ' par(es).');
    break;
  }
  chamadas++;
  processar(r);
  console.log('pagina ' + p + '/' + totalPaginas + ' - OS lidas ' + osLidas + ', com RF ' + pares.length);
}

// Dedup: mesma (rf, cNumOs) nao precisa entrar duas vezes.
const vistos = new Set();
const unicos = [];
for (const p of pares) {
  const k = p.rf + '|' + p.cNumOs;
  if (vistos.has(k)) continue;
  vistos.add(k);
  unicos.push(p);
}

console.log('total: ' + osLidas + ' OS lidas, ' + unicos.length + ' com RF, '
  + osSemRF + ' sem RF, ' + divergentes.length + ' divergentes');

return [{
  json: {
    DRY_RUN: DRY_RUN,
    modo: MODO,
    chamadas_api: chamadas,
    pagina_inicial: PAGINA_INICIAL,
    total_paginas: totalPaginas,
    total_registros_omie: totalRegistros,
    parcial: parcial,
    proxima_pagina: proxima_pagina,
    motivo_parada: motivo_parada,
    os_lidas: osLidas,
    os_sem_rf: osSemRF,
    divergentes: divergentes.slice(0, 20),
    qtd_divergentes: divergentes.length,
    pares: unicos,
  },
}];

// =====================================================================
// Monta o SQL em LOTES. Dois sabores, o IF escolhe qual roda:
//   sql_diag   -> SELECT de diagnostico (nao grava nada)
//   sql_insert -> INSERT ... SELECT com o JOIN na NF (grava)
// Mode: Run Once for All Items
//
// O JOIN acontece NO BANCO: os pares (rf, cNumOs) vem da Omie e a nota vem
// da NF por cNumOs. OS sem nota correspondente e' simplesmente ignorada
// pelo JOIN -- e contada no diagnostico.
// =====================================================================

const TB_NOTA  = 'kvm4_db.rf_nota';
const TB_NF    = 'kvm4_db.NF';
const TB_ENVIO = 'kvm4_db.rfs_faturados';
const LOTE = 400;

const d = $input.first().json;
const pares = Array.isArray(d.pares) ? d.pares : [];

if (!pares.length) {
  throw new Error('Nenhum par RF/OS colhido da Omie. Confira as credenciais e o filtro apenas_importado_api = S.');
}

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "''");

// tabela derivada com os pares deste lote
function derivada(bloco) {
  return bloco.map(function (p, i) {
    const st = p.status_nota ? "'" + esc(p.status_nota) + "'" : 'NULL';
    const sel = i === 0 ? 'SELECT ' : 'UNION ALL SELECT ';
    return sel + "'" + esc(p.rf) + "' AS rf, '" + esc(p.cNumOs) + "' AS cNumOs, "
      + st + ' AS status_nota';
  }).join(' ');
}

const saida = [];

for (let i = 0; i < pares.length; i += LOTE) {
  const bloco = pares.slice(i, i + LOTE);
  const t = '(' + derivada(bloco) + ') t';

  // ---- diagnostico: o que ACONTECERIA, sem gravar ----
  const sql_diag =
    'SELECT COUNT(*) AS pares_no_lote,'
    + ' SUM(n.nIdNf IS NOT NULL) AS com_nota,'
    + ' SUM(n.nIdNf IS NULL) AS sem_nota,'
    + ' SUM(n.nIdNf IS NOT NULL AND f.rf IS NULL) AS rf_invisivel_hoje,'
    + ' SUM(x.rf IS NOT NULL) AS ja_na_rf_nota,'
    + " SUM(t.status_nota = 'CANCELADA') AS canceladas,"
    // Nomeia os casos sem nota em vez de so' contar: sao poucos (3 em
    // 3.172 na medicao de 10/08/2026) e cada um precisa de olho humano --
    // OS nunca faturada e' comportamento CORRETO (nao houve cobranca, o RF
    // deve seguir liberado), nao um buraco.
    + " GROUP_CONCAT(IF(n.nIdNf IS NULL, CONCAT(t.rf,'@OS',t.cNumOs), NULL)"
    + "   ORDER BY t.rf SEPARATOR ' | ') AS quais_sem_nota"
    + ' FROM ' + t
    + ' LEFT JOIN ' + TB_NF + ' n ON n.cNumOs = t.cNumOs'
    + ' LEFT JOIN ' + TB_ENVIO + ' f ON f.rf = t.rf'
    + ' LEFT JOIN ' + TB_NOTA + ' x ON x.rf = t.rf AND x.nIdNf = n.nIdNf';

  // ---- gravacao: INSERT IGNORE, idempotente pela PK (rf, nIdNf) ----
  const sql_insert =
    'INSERT IGNORE INTO ' + TB_NOTA
    + ' (rf, nIdNf, cNumNFSe, cNumOs, emp, status_nota, status_em, origem)'
    + ' SELECT t.rf, n.nIdNf, n.cNumNFSe, n.cNumOs, n.emp, t.status_nota, NOW(), '
    + "'BACKFILL'"
    + ' FROM ' + t
    + ' JOIN ' + TB_NF + ' n ON n.cNumOs = t.cNumOs';

  saida.push({
    json: {
      lote: saida.length + 1,
      pares_no_lote: bloco.length,
      sql: d.DRY_RUN ? sql_diag : sql_insert,
      modo: d.DRY_RUN ? 'DIAGNOSTICO' : 'GRAVACAO',
    },
  });
}

console.log(saida.length + ' lote(s) de ' + LOTE + ' para ' + pares.length + ' par(es).');
return saida;

// =====================================================================
// Consolida o diagnostico dos lotes (DRY RUN -- nada foi gravado).
// Mode: Run Once for All Items
// =====================================================================

const linhas = $input.all().map((i) => i.json);
const varre = $('Varre_OS_Omie').first().json;

const soma = (campo) => linhas.reduce(function (a, l) {
  const v = Number(l[campo]);
  return a + (isFinite(v) ? v : 0);
}, 0);

const com_nota = soma('com_nota');
const sem_nota = soma('sem_nota');
const invisiveis = soma('rf_invisivel_hoje');
const ja_tem = soma('ja_na_rf_nota');
const canceladas = soma('canceladas');

// junta a lista dos casos sem nota vinda de todos os lotes
const quais = linhas
  .map(function (l) { return l.quais_sem_nota; })
  .filter(Boolean)
  .join(' | ')
  .split(' | ')
  .filter(Boolean);

return [{
  json: {
    modo: 'DRY RUN - nada foi gravado na rf_nota',
    modo_varredura: varre.modo,
    varredura: varre.parcial
      ? 'PARCIAL - parou na pagina ' + varre.proxima_pagina + ' de ' + varre.total_paginas
        + '. Rode de novo com PAGINA_INICIAL = ' + varre.proxima_pagina + '.'
      : 'COMPLETA (' + varre.total_paginas + ' pagina(s))',
    motivo_parada: varre.motivo_parada || null,
    chamadas_api: varre.chamadas_api,

    os_lidas: varre.os_lidas,
    os_sem_rf: varre.os_sem_rf,
    os_com_rf: (varre.pares || []).length,
    rf_divergente_entre_campos: varre.qtd_divergentes,
    exemplos_divergentes: varre.divergentes,

    vinculos_que_seriam_criados: com_nota - ja_tem,
    ja_existentes_na_rf_nota: ja_tem,
    sem_nota_correspondente: sem_nota,
    quais_sem_nota: quais,
    sobre_os_sem_nota:
      'Cada item e "RF@OS". Confira o cFaturada da OS na Omie: se for "N", a OS '
      + 'NUNCA foi faturada -- nao existe nota, nada foi cobrado, e o RF DEVE seguir '
      + 'liberado (comportamento correto, nao buraco). Se for "S" e ainda assim nao ha '
      + 'nota na NF, ai vale investigar: a nota pode ter sido cancelada antes do fluxo '
      + 'diario passar, e nesse caso o RF esta desprotegido.',
    marcados_como_cancelada: canceladas,

    RF_INVISIVEIS_HOJE: invisiveis,
    o_que_isso_significa:
      invisiveis + ' RF(s) tem nota na Omie mas NAO estao em rfs_faturados: hoje '
      + 'passariam batido no verificador e poderiam ser refaturados. E o buraco '
      + 'que o backfill fecha.',

    proximo_passo: varre.parcial
      ? 'Varredura parcial: complete antes de gravar, senao o backfill fica incompleto.'
      : 'Confira os numeros e vire DRY_RUN = false no no Config para gravar.',
  },
}];

// Resumo da GRAVACAO.
// Lembrete: o no MySQL do n8n so' devolve affectedRows se a opcao
// "Output Query Execution Details" estiver ligada no no Gravar_Vinculos.
const itens = $input.all().map((i) => i.json);
const varre = $('Varre_OS_Omie').first().json;

let afetadas = null;
for (const it of itens) {
  const n = it && it.data && it.data.affectedRows;
  if (typeof n === 'number') afetadas = (afetadas || 0) + n;
}

return [{
  json: {
    modo: 'GRAVACAO concluida',
    lotes_executados: itens.length,
    pares_enviados: (varre.pares || []).length,
    vinculos_gravados: afetadas === null
      ? 'ligue "Output Query Execution Details" no no Gravar_Vinculos para ver o numero'
      : afetadas,
    varredura: varre.parcial ? 'PARCIAL - faltou da pagina ' + varre.proxima_pagina + ' em diante' : 'COMPLETA',
    conferir: 'SELECT origem, COUNT(*) FROM kvm4_db.rf_nota GROUP BY origem;',
  },
}];
